CREATE DATABASE IF NOT EXISTS sifemklen CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE sifemklen;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS activity_logs,settings,payments,staff_assignments,bookings,staff,services,service_categories,customers,admins,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30) NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','customer') NOT NULL DEFAULT 'customer',status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_users_role(role),INDEX idx_users_status(status)) ENGINE=InnoDB;
CREATE TABLE customers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,address VARCHAR(255) NOT NULL,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_customers_user FOREIGN KEY(user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE CASCADE,INDEX idx_customer_status(status)) ENGINE=InnoDB;
CREATE TABLE admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_admins_user FOREIGN KEY(user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE service_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_name VARCHAR(100) NOT NULL UNIQUE,description TEXT,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE services(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,service_name VARCHAR(150) NOT NULL,description TEXT,price DECIMAL(12,2) NOT NULL DEFAULT 0.00,duration VARCHAR(50) NOT NULL,image VARCHAR(255) NULL,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_services_category FOREIGN KEY(category_id) REFERENCES service_categories(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_services_category(category_id),INDEX idx_services_status(status)) ENGINE=InnoDB;
CREATE TABLE bookings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_reference VARCHAR(40) NOT NULL UNIQUE,customer_id INT UNSIGNED NOT NULL,service_id INT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,service_date DATE NOT NULL,service_time TIME NOT NULL,service_address VARCHAR(255) NOT NULL,notes TEXT,estimated_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,status ENUM('Pending','Confirmed','Assigned','In Progress','Completed','Cancelled') NOT NULL DEFAULT 'Pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_bookings_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON UPDATE CASCADE ON DELETE RESTRICT,CONSTRAINT fk_bookings_service FOREIGN KEY(service_id) REFERENCES services(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_bookings_customer(customer_id),INDEX idx_bookings_service(service_id),INDEX idx_bookings_status(status),INDEX idx_bookings_date(service_date)) ENGINE=InnoDB;
CREATE TABLE staff(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,position ENUM('Manager','Cleaner','Laundry Specialist','Supervisor','Driver','Customer Support') NOT NULL DEFAULT 'Cleaner',address VARCHAR(255),status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_staff_status(status)) ENGINE=InnoDB;
CREATE TABLE staff_assignments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL,staff_id INT UNSIGNED NOT NULL,assigned_by INT UNSIGNED NOT NULL,assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',CONSTRAINT fk_assign_booking FOREIGN KEY(booking_id) REFERENCES bookings(id) ON UPDATE CASCADE ON DELETE CASCADE,CONSTRAINT fk_assign_staff FOREIGN KEY(staff_id) REFERENCES staff(id) ON UPDATE CASCADE ON DELETE RESTRICT,CONSTRAINT fk_assign_admin FOREIGN KEY(assigned_by) REFERENCES users(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_assignment_booking(booking_id),INDEX idx_assignment_staff(staff_id)) ENGINE=InnoDB;
CREATE TABLE payments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_reference VARCHAR(40) NOT NULL UNIQUE,booking_id INT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,payment_method ENUM('Cash','Bank Transfer','Card') NOT NULL DEFAULT 'Cash',payment_status ENUM('Pending','Paid','Failed','Refunded') NOT NULL DEFAULT 'Pending',payment_date DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_payments_booking FOREIGN KEY(booking_id) REFERENCES bookings(id) ON UPDATE CASCADE ON DELETE CASCADE,INDEX idx_payment_status(payment_status),INDEX idx_payment_date(payment_date)) ENGINE=InnoDB;
CREATE TABLE activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,activity VARCHAR(120) NOT NULL,description TEXT NOT NULL,ip_address VARCHAR(45),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_logs_user FOREIGN KEY(user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE SET NULL,INDEX idx_logs_created(created_at),INDEX idx_logs_activity(activity)) ENGINE=InnoDB;
CREATE TABLE settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(80) NOT NULL UNIQUE,setting_value TEXT NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
